// SURFACE SESSIONS (`a-noun-and-its-verbs-launch-their-personas`) — the pane grammar and charter for
// the two personas that live on the crate drill.
//
// A NOUN gets an OPERATOR: it drives `bsc <noun>` for real work and reports what using it COSTS.
// A VERB gets a MAINTAINER: it owns that verb and answers the operator.
//
// They are app-owned sessions, exactly like the studio sessions and the per-request debug sessions —
// not fleet panes. A fleet pane is `<project>:<stream>` and belongs to a plan stream; these belong to a
// NODE in the graph, so the pane id is derived from the node and nothing else has to record the link.
import type { CrateDrillDoc } from "@/features/glance/lib/surfaceNodes";
import type { AgentProfile } from "@/shared/lib/security/agentProfiles";

/** Every surface session's pane lives under one prefix, so `livePanesFor…` can recognise them. */
export const SURFACE_PANE_PREFIX = "surface-studio:";

/** The pane a NOUN's operator runs in. */
export const nounPaneId = (noun: string): string => `${SURFACE_PANE_PREFIX}noun-${noun}`;

/** The pane a VERB's maintainer runs in — keyed on BOTH, since `logs summary` and `perf summary` are
 *  different commands and must not share a session. */
export const verbPaneId = (noun: string, verb: string): string =>
  `${SURFACE_PANE_PREFIX}verb-${noun}-${verb}`;

/**
 * The app-owned pane for a crate-drill node, or null if the node is not one.
 *
 * DERIVED FROM THE NODE ID, never recorded anywhere. That is what makes a session answerable from the
 * graph alone: the node knows its pane, so liveness, opening and killing all resolve without a second
 * table to keep in sync — the same property `requestIdFromPaneId` relies on.
 */
export function surfacePaneIdForNode(nodeId: string): string | null {
  if (nodeId.startsWith("noun:")) return nounPaneId(nodeId.slice("noun:".length));
  if (nodeId.startsWith("verb:")) {
    const rest = nodeId.slice("verb:".length);
    const at = rest.indexOf(":");
    // A verb node id is `verb:<noun>:<verb>`; anything else is not one, and guessing would mint a pane
    // that nothing can ever match back to a node.
    if (at <= 0 || at === rest.length - 1) return null;
    return verbPaneId(rest.slice(0, at), rest.slice(at + 1));
  }
  return null;
}

/** What a surface session is: which persona, and what it is pointed at. */
export interface SurfaceAssignment {
  kind: "operator" | "maintainer";
  crate: string;
  /** The crate's REPO-RELATIVE directory (`crates/logs`), carried as data rather than derived from
   *  `crate`. A session runs HERE, not at the repo root — see the cwd note on `surfaceCharter` — and
   *  `crates/${crate}` would be a guess about a layout the drill already states. */
  path: string;
  noun: string;
  verb?: string;
}

/** The assignment behind a node, or null. `doc` names the crate the drill is showing. */
export function surfaceAssignment(nodeId: string, doc: CrateDrillDoc | null): SurfaceAssignment | null {
  if (!doc) return null;
  if (nodeId.startsWith("noun:")) {
    return { kind: "operator", crate: doc.crate, path: doc.path, noun: nodeId.slice("noun:".length) };
  }
  if (nodeId.startsWith("verb:")) {
    const rest = nodeId.slice("verb:".length);
    const at = rest.indexOf(":");
    if (at <= 0 || at === rest.length - 1) return null;
    return { kind: "maintainer", crate: doc.crate, path: doc.path, noun: rest.slice(0, at), verb: rest.slice(at + 1) };
  }
  return null;
}

/** The exact command line for one verb, as the session must type it. */
const verbLine = (noun: string, verb: string, summary: string): string =>
  `  bsc ${noun} ${verb}${" ".repeat(Math.max(1, 22 - noun.length - verb.length))}${summary}`;

/**
 * The session's opening instruction: the PERSONA'S OWN PROMPT, then this session's assignment.
 *
 * `startPrompt` is passed in rather than inlined, because it is read from the persona store at launch
 * (`bsc persona get`). That keeps ONE copy of what an operator or a maintainer is — edit the persona and
 * every session started afterwards changes, with no second text to remember.
 *
 * # It TEACHES the surface rather than sending the session to discover it
 *
 * This used to open with "Read it first with `bsc <noun> help` and `bsc surface drill <crate> --json`",
 * which cost a local model two turns of a twenty-turn budget before it had run anything — and left it
 * inferring the command SHAPE from whatever it had seen. MEASURED 2026-09-03: a session reached for
 * `bsc-studio-help`, generalising from the hyphenated `bsc-ask`/`bsc-answer` helpers it had been
 * granted, which is not a command at all. The drill document is already in hand at launch, so the
 * verbs are listed here as literal command lines and the hyphen rule is stated rather than left to be
 * inferred.
 *
 * `verbs: null` means the crate serves this noun but publishes no `CmdDoc` catalog — DISTINCT from an
 * empty list, and said so rather than rendered as "no verbs", which would read as a broken surface.
 */
export function surfaceCharter(a: SurfaceAssignment, startPrompt: string, doc?: CrateDrillDoc | null): string {
  const row = doc?.nouns.find((n) => n.noun === a.noun);
  const verbs = row?.verbs ?? null;

  // THE SHAPE, stated once and shared by both personas. `bsc <noun> <verb>` is spaced; the ONLY
  // hyphenated names are the small shell-helper family, and conflating them produces a command that
  // does not exist.
  const shape =
    `THE BINARY IS \`bsc\`, already on your PATH, and EVERYTHING you can run is a subcommand of it:\n` +
    `  bsc help              every surface this app has\n` +
    `  bsc <noun> help       one surface in detail\n` +
    `  bsc persona whatami   who this session is, and what it may run\n\n` +
    `THE SHAPE IS SPACED, NEVER HYPHENATED. It is \`bsc ${a.noun} <verb>\` — three words. ` +
    `\`bsc-${a.noun}-<verb>\` is not a command and never was, and neither is \`bsc-session\` or ` +
    `\`bsc-${a.noun}-help\`. The only hyphenated names are the shell helpers (\`bsc-ask\`, ` +
    `\`bsc-answer\`), which are a different, tiny family — everything else is \`bsc\` then a space.\n\n` +
    `YOUR GRANT IS NARROWER THAN THAT CATALOG. \`bsc help\` lists what the APP has; you auto-run only ` +
    `your own surface plus the reporting verbs below. A command outside it will stop and ask rather ` +
    `than run, so reach for what you were given here instead of probing for what you were not.`;

  const catalog =
    verbs === null
      ? `This crate serves \`bsc ${a.noun}\` but publishes no verb catalog, so run \`bsc ${a.noun} help\` ` +
        `once to see what it takes. That is the exception, not the rule.`
      : `ITS VERBS, IN FULL — this is the whole surface, so you never need to discover it:\n` +
        verbs.map((v) => verbLine(a.noun, v.verb, v.summary)).join("\n") +
        `\n\nEach takes \`help\` for its own detail (\`bsc ${a.noun} <verb> help\`).`;

  const head =
    a.kind === "operator"
      ? `YOUR SURFACE IS \`bsc ${a.noun}\`, implemented by the \`${a.crate}\` crate at \`${a.path}\`.\n\n` +
        `${shape}\n\n${catalog}\n\n` +
        `TAKE ONE VERB, use it against something real, and ask ITS MAINTAINER for the change. Each verb ` +
        `has its own session, and the id is derived from the verb — no lookup:\n` +
        (verbs === null
          ? `  bsc session ask surface-studio:verb-${a.noun}-<verb> "<what it cost, and the exact command>"`
          : verbs
              .map((v) => `  bsc session ask surface-studio:verb-${a.noun}-${v.verb} "<…>"`)
              .join("\n"))
      : `YOU MAINTAIN \`bsc ${a.noun}${a.verb ? " " + a.verb : ""}\`, in the \`${a.crate}\` crate at ` +
        `\`${a.path}\` — the directory you are running in.\n\n${shape}\n\n` +
        (verbs?.find((v) => v.verb === a.verb)?.usage
          ? `WHAT YOUR VERB TAKES TODAY:\n${verbs.find((v) => v.verb === a.verb)!.usage}\n\n`
          : "") +
        `The operator of this noun asks you directly — that ask is your job, and you answer on the same ` +
        `loop with \`bsc session reply <loop-id> "<…>"\`.\n\n` +
        `If you change what this verb returns by default, update its \`CmdDoc\` in the same change: ` +
        `\`bsc surface verbs ${a.noun}\`, the Glance drill AND the charter above all PROJECT that catalog, ` +
        `so a stale entry advertises what dispatch will refuse — and teaches the operator a command that ` +
        `does not run.`;
  return `${startPrompt}\n\n---\n\n${head}\n`;
}

/** The profile id for an operator pointed at `noun`. Derived, so re-opening the same noun reuses the
 *  one profile instead of minting a new row per launch. */
export const surfaceOperatorProfileId = (noun: string): string => `gen_surface_${noun}`;

/**
 * The per-pane permission profile that hands an operator ITS OWN NOUN, and nothing else
 * (`surface-operator-runs-confined-to-its-own-noun`).
 *
 * # Why the noun cannot live in the role
 *
 * `build_allow_rules` returns EARLY under `restricted_allow` with only the wrapped `allowedCommands`
 * — no baseline tiers, no mandatory tier, no `Bash(bsc-*)`. A confined session therefore auto-runs
 * exactly what its allow list names and nothing else. A designer never notices, because it is
 * one-noun-per-ROLE and `bsc ui` sits in its floor; an operator's noun is chosen per SESSION, so a
 * static role structurally cannot name it. `buildSessionSettings` composes
 * `[...prof.allowedCommands, ...restrictedCommands]`, and this profile is the first half.
 *
 * # `bash` MUST NOT be `allow`, and that is the whole safety argument
 *
 * `resolveProfileSettings` maps a tool tier of `allow` to a VERBATIM tool rule — so `bash: "allow"`
 * emits a bare `Bash`, which auto-approves every command and silently reopens the confinement this
 * profile exists to create. `deny` is explicitly skipped for `bash` (a blanket Bash deny would also
 * kill the guaranteed `git`/`gh`), so it emits no rule at all and shell control stays entirely with
 * the allow list. `deny` is therefore the only correct value here, and
 * `theOperatorProfileNeverBlanketAllowsBash` pins it.
 *
 * The two `bsc-*` entries are shell FUNCTIONS from `bsc-env.sh`, not the binary — `Bash(bsc *)` cannot
 * match them (no space after `bsc`), and the blanket `Bash(bsc-*)` that every unconfined posture gets
 * is on the far side of that early return. The operator's charter tells it to reach its maintainer
 * with `bsc-ask`, so the grant has to be explicit here or the instruction is one it cannot follow.
 */
export function surfaceOperatorProfile(noun: string): AgentProfile {
  return {
    id: surfaceOperatorProfileId(noun),
    name: `Surface operator · bsc ${noun}`,
    color: "oklch(0.72 0.10 230)",
    category: "generated",
    origin: "generated by the surface studio",
    desc: `Drives \`bsc ${noun}\` and reports what it cost. No build toolchain, no file writes.`,
    mode: "deny",
    commands: [`bsc ${noun}`, "bsc-ask", "bsc-answer"],
    // `read`/`grep`/`glob` so it can look at what a verb wrote; everything that MUTATES is denied,
    // and `bash` is denied so no blanket rule is emitted (see above).
    tools: {
      read: "allow",
      grep: "allow",
      glob: "allow",
      edit: "deny",
      write: "deny",
      bash: "deny",
      web: "deny",
      task: "deny",
    },
    // It reports on a surface; it never edits one. The role already holds `code: none` — this is the
    // same statement at the tool layer, where a path-scoped rule can actually enforce it.
    paths: { allow: [], deny: ["**/*"] },
    net: { allow: [] },
  };
}
